function findCandidates(lat, lng, product, minCount=5, maxK=6):
  origin = h3.latLngToCell(lat, lng, 9)
  seen = set(); out = []
  for k in [1, 2, 4, 6]:
    if k > maxK: break
    for cell in h3.gridDisk(origin, k) - seen:
      seen.add(cell)
      shard = ring.lookup(cityOf(cell), parent(cell, 6))
      for d in shard.driversIn(cell):
        if d.state == AVAILABLE and d.product == product and now - d.ts < 15s:
          out.append(d)
    if len(out) >= minCount: break
  out.sort(by = haversine(lat, lng, d.lat, d.lng))
  return out[:20]   # then road ETA ranks these

every 1500ms for zone in cityZones:
  R = openRequests(zone); D = availableDrivers(zone, margin=2km)
  C = matrix(|R| x |D|, INF)
  for r in R:
    cands = topK(D near r, 20)
    etas = eta.manyToOne([d.pos for d in cands], r.pickup)
    for d, t in zip(cands, etas):
      if t < 15min: C[r][d] = t + w1*(1-pAccept(d,r)) + w2*deadhead(r,d)
  pairs = hungarian(C)        # or auction / min-cost flow when large
  for (r, d) in pairs where C[r][d] < INF:
    if lease.tryReserve(d, r.trip): sendOffer(d, r)
    else: requeue(r)          # lost race, next tick

function chQuery(s, t):
  dF = {s:0}; dB = {t:0}; best = INF
  pqF = [(0,s)]; pqB = [(0,t)]
  while pqF or pqB:
    for (pq, d, other) in [(pqF,dF,dB), (pqB,dB,dF)]:
      if not pq: continue
      (k, u) = pq.pop()
      if k > best: pq.clear(); continue
      if u in other: best = min(best, d[u] + other[u])
      for (u, v, w) in upwardEdges(u):      # only to higher rank
        if d[u] + w < d.get(v, INF): d[v] = d[u] + w; pq.push((d[v], v))
  return best

eta = chQuery(snap(src), snap(dst)) * 1.0
eta = eta + residualModel(eta, hourOfWeek, city, weather, routeFeatures)

ALLOWED = {REQUESTED:[MATCHED,CANCELLED,EXPIRED], MATCHED:[ARRIVED,CANCELLED],
           ARRIVED:[ON_TRIP,CANCELLED], ON_TRIP:[COMPLETED], COMPLETED:[], ...}
function transition(tripId, event, expectedVersion):
  trip = db.get(tripId)
  if trip.lastEventId == event.id: return trip          # idempotent replay
  to = target(trip.state, event)
  if to not in ALLOWED[trip.state]: return 409(trip)
  tx: ok = db.update(tripId, set state=to, version=v+1, lastEventId=event.id,
                      where version == expectedVersion)
      if ok: outbox.insert(TripEvent(tripId, to, v+1))
  return ok ? trip' : 409(db.get(tripId))
